use serde_json::{json,Value};
use std::{fs,path::Path,process::Command};
fn main(){let root=Path::new("/tmp/zopro-front-snapshot-fence");let mut text=String::new();let mut records=Vec::new();for(label,path)in [("accepted","/tmp/zopro-grouping-module/native/candidate/artifacts.json"),("candidate","/tmp/zopro-front-snapshot-fence/native/candidate/artifacts.json")]{let metadata:Value=serde_json::from_slice(&fs::read(path).unwrap()).unwrap();let binary=metadata["binary"].as_str().unwrap();let nm=Command::new("nm").args(["-S","-C",binary]).output().unwrap();assert!(nm.status.success());let nm=String::from_utf8(nm.stdout).unwrap();for target in ["<rayon_core::registry::WorkerThread>::wait_until_cold","<crossbeam_deque::deque::Stealer<rayon_core::job::JobRef>>::steal"]{let hits=nm.lines().filter(|l|l.ends_with(target)).collect::<Vec<_>>();assert_eq!(hits.len(),1);let fields=hits[0].split_whitespace().collect::<Vec<_>>();let start=u64::from_str_radix(fields[0],16).unwrap();let size=u64::from_str_radix(fields[1],16).unwrap();let args=["-d".to_owned(),"-C".to_owned(),format!("--start-address=0x{start:x}"),format!("--stop-address=0x{:x}",start+size),binary.into()];let output=Command::new("objdump").args(&args).output().unwrap();assert!(output.status.success());text.push_str(&format!("\n{label}: {target}, {size} bytes\n"));text.push_str(&String::from_utf8(output.stdout).unwrap());records.push(json!({"variant":label,"binary":binary,"binary_sha256":metadata["binary_sha256"],"symbol":target,"start_hex":format!("0x{start:x}"),"size_bytes":size,"objdump_argv":args}));}}
fs::write(root.join("codegen.txt"),text).unwrap();fs::write(root.join("codegen-review.json"),format!("{}\n",serde_json::to_string_pretty(&json!({"status":"captured","symbols":records,"scope":"Exact linked SDK scalar steal and containing wait_until_cold routines, accepted/candidate. Snapshot helper is inlined; absence of a separate symbol does not establish absence of code. Static sizes/instructions do not establish dynamic cost or cause of latency. Source audit checks intended ordering; complete SDK timings determine performance."})).unwrap())).unwrap();println!("CODEGEN_CAPTURED4exactlinkedroutines");}
